import HowItWorksSectionV1 from "./how-it-works-section-v1"

export default function Page() {
  return <HowItWorksSectionV1 />
}

"use client"

import { steps } from "../lib/steps"
import StepCard from "./step-card"

export default function StepsGrid() {
  return (
    <div className="hiw1-grid relative grid grid-cols-1 gap-12 sm:grid-cols-2 lg:grid-cols-3 lg:gap-10">
      {steps.map((step, i) => (
        <div key={step.id} className="hiw1-step-item relative isolate">
          <StepCard step={step} />
          {i < steps.length - 1 ? (
            <>
              {/* Horizontal beam — spans the gap to the right card.
                  i=0: visible sm+ (cards 0 & 1 are same row at both sm and lg)
                  i=1: visible lg only (cards 1 & 2 share a row only in 3-col) */}
              <span
                aria-hidden
                className={
                  i === 0
                    ? "hiw1-beam-h pointer-events-none absolute top-1/2 hidden -translate-y-1/2 sm:block"
                    : "hiw1-beam-h pointer-events-none absolute top-1/2 hidden -translate-y-1/2 lg:block"
                }
              />
              {/* Vertical beam — spans the row gap downward.
                  i=0: visible mobile + sm (at sm, card 0 and card 2 are both col-1
                       so this connects them across the row gap)
                  i=1: visible mobile only (at sm, card 1 is col-2 with nothing below) */}
              <span
                aria-hidden
                className={
                  i === 0
                    ? "hiw1-beam-vertical pointer-events-none absolute -bottom-12 left-1/2 h-12 w-px -translate-x-1/2 lg:hidden"
                    : "hiw1-beam-vertical pointer-events-none absolute -bottom-12 left-1/2 h-12 w-px -translate-x-1/2 sm:hidden"
                }
              />
            </>
          ) : null}
        </div>
      ))}
    </div>
  )
}

import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import type { Step } from "../lib/steps"

type Props = {
  step: Step
}

export default function StepCard({ step }: Props) {
  return (
    <Card className="flex h-full flex-col rounded-[2rem] py-0">
      <CardHeader className="p-8 pb-0">
        <CardTitle className="hiw1-step-number text-base">
          {step.number}
        </CardTitle>
      </CardHeader>
      <CardContent className="flex flex-1 flex-col p-8 pb-12 pt-6">
        <CardTitle className="font-pixel-grid text-[2.75rem] leading-[1.05] font-medium tracking-tight text-foreground/90">
          {step.title}
        </CardTitle>
        <CardDescription className="mt-auto pt-4 text-[15px] leading-relaxed text-muted-foreground/80 line-clamp-4 min-h-24">
          {step.description}
        </CardDescription>
      </CardContent>
    </Card>
  )
}

export type Step = {
  id: string
  number: string
  title: string
  description: string
}

export const steps: Step[] = [
  {
    id: "browse",
    number: "01",
    title: "Browse",
    description:
      "Explore a growing library of UI blocks built with Next.js, Tailwind CSS, and shadcn/ui. Find the right one and you are halfway there.",
  },
  {
    id: "copy",
    number: "02",
    title: "Copy",
    description:
      "Paste the code straight into your project. No installs, no wrappers and no lock in. Just clean components that you fully own.",
  },
  {
    id: "ship",
    number: "03",
    title: "Ship",
    description:
      "Every block is styled, responsive and ready to go. Take your idea straight to production without writing a single line of boilerplate.",
  },
]

.hiw1-theme {
  --hiw1-accent: #16a34a;
}

.dark .hiw1-theme {
  --hiw1-accent: #4ade80;
}

.hiw1-step-number {
  color: var(--hiw1-accent);
}

/* ─── Animated dashed connector beam ─────────────────────────── */

/* Horizontal gap connector — width matches the grid gap at each breakpoint */
.hiw1-beam-h {
  /* sm: gap-12 = 3rem */
  right: -3rem;
  width: 3rem;
  height: 2px;
  background-image: repeating-linear-gradient(
    90deg,
    var(--hiw1-accent) 0 4px,
    transparent 4px 8px
  );
  background-size: 16px 2px;
  animation: hiw1-dash-flow 1.5s linear infinite;
}

/* lg: gap-10 = 2.5rem */
@media (min-width: 1024px) {
  .hiw1-beam-h {
    right: -2.5rem;
    width: 2.5rem;
  }
}

.hiw1-beam-vertical {
  width: 2px;
  background-image: repeating-linear-gradient(
    180deg,
    var(--hiw1-accent) 0 4px,
    transparent 4px 8px
  );
  background-size: 2px 16px;
  animation: hiw1-dash-flow-v 1.5s linear infinite;
}

@keyframes hiw1-dash-flow {
  to {
    background-position: 16px 0;
  }
}

@keyframes hiw1-dash-flow-v {
  to {
    background-position: 0 16px;
  }
}

/* ─── Accent color for heading prefix ───────────────────────── */

.hiw1-accent {
  color: var(--hiw1-accent);
}

/* ─── Reduced motion ─────────────────────────────────────────── */

@media (prefers-reduced-motion: reduce) {
  .hiw1-beam-h,
  .hiw1-beam-vertical {
    animation: none;
    background-position: 0 0;
  }
}
